<?php if ($error): ?><div class="admin-error" role="alert"><?= escape($error) ?> <?php if (str_contains($error, 'no longer available')): ?>Check the conflict override below only if you have reviewed the therapist’s calendar and accept the overlap.<?php endif; ?></div><?php endif; ?>
<section class="admin-section manual-panel"><p class="admin-eyebrow">RECEPTION BOOKING</p><h2>Create a customer appointment</h2><p>Use this for phone bookings and walk-ins. Times use Africa/Accra business hours.</p>
<form method="post" class="admin-form manual-form"><input type="hidden" name="csrf" value="<?= escape(Csrf::token()) ?>">
<div class="form-two"><label>Treatment<select name="service_id" required><option value="">Choose treatment</option><?php foreach($services as $service): ?><option value="<?= $service['id'] ?>" <?= (string)($old['service_id']??'')===(string)$service['id']?'selected':'' ?>><?= escape($service['name']) ?> · <?= money($service['price']) ?></option><?php endforeach; ?></select></label><label>Therapist<select name="staff_id"><option value="">First available</option><?php foreach($staff as $person): ?><option value="<?= $person['id'] ?>" <?= (string)($old['staff_id']??'')===(string)$person['id']?'selected':'' ?>><?= escape($person['name']) ?></option><?php endforeach; ?></select></label></div>
<label>Appointment date and time<input type="datetime-local" name="local_start" required value="<?= escape($old['local_start'] ?? '') ?>"></label><input type="hidden" name="start" id="manual-start" value="<?= escape($old['start'] ?? '') ?>">
<div class="form-two"><label>Customer name<input name="name" autocomplete="name" required value="<?= escape($old['name'] ?? '') ?>"></label><label>Ghana phone<input type="tel" name="phone" autocomplete="tel" required value="<?= escape($old['phone'] ?? '') ?>"></label></div><label>Email (optional)<input type="email" name="email" value="<?= escape($old['email'] ?? '') ?>"></label><label>Appointment notes<textarea name="notes" rows="4" maxlength="1000"><?= escape($old['notes'] ?? '') ?></textarea></label>
<div class="form-two"><label>Booking status<select name="status"><option value="confirmed" <?= ($old['status']??'')==='confirmed'?'selected':'' ?>>Confirmed</option><option value="pending" <?= ($old['status']??'')==='pending'?'selected':'' ?>>Pending</option></select></label><label>Payment at spa<select name="payment_status"><option value="unpaid">Unpaid</option><option value="paid" <?= ($old['payment_status']??'')==='paid'?'selected':'' ?>>Already paid</option></select></label></div>
<label class="check-row"><input type="checkbox" name="policy_accepted" value="1" required> The customer has been told about the cancellation policy</label><label class="check-row override-check"><input type="checkbox" name="override" value="1" <?= ($old['override']??'')==='1'?'checked':'' ?>> Override a booking conflict <small>Only after reviewing the calendar. This does not bypass working hours, breaks, holidays, or past-date rules. The override is recorded in the audit history.</small></label>
<button class="admin-button" type="submit">Create booking</button></form></section>
<script>document.querySelector('.manual-form').addEventListener('submit',function(event){const local=this.elements.local_start.value;if(local){this.elements.start.value=local.length===16?local.replace('T',' ')+':00':local.replace('T',' ');}if(!this.elements.start.value){event.preventDefault();}});</script>
